// aim.cpp - Aim-assist math for the game client.
//
// Takes the camera's view-projection matrix and a list of entity head positions
// (supplied by the engine's own entity system), projects them to screen space,
// picks the best target inside a screen-space cone around the crosshair, and
// returns a smoothed crosshair delta in pixels. The caller feeds that delta into
// its own camera/look controller. No platform dependencies.
//
// Matrix convention: row-major storage, column vectors (clip = M * [x y z 1]^T).
// If your engine uses row vectors (D3DX-style, clip = v * M), pass the transpose.
//
// Build (smoke test):
//   cl /std:c++17 /EHsc /DAIM_SMOKE aim.cpp
//   clang++ -std=c++17 -DAIM_SMOKE aim.cpp -o aim

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <vector>

namespace aim {

struct Vec2 { float x = 0.f, y = 0.f; };
struct Vec3 { float x = 0.f, y = 0.f, z = 0.f; };
struct Mat4 { float m[4][4] = {}; };

struct Entity {
    uint32_t id = 0;
    Vec3     head;          // world-space head position
    bool     alive = true;
    bool     visible = true; // engine-side line-of-sight result
};

struct Config {
    float coneRadiusPx   = 240.f; // only targets within this radius of the crosshair count
    float smoothTimeSec  = 0.08f; // exponential smoothing time constant (smaller = snappier)
    float maxSpeedPxSec  = 2400.f;// hard cap on crosshair speed
    float stickyBonusPx  = 40.f;  // current target is favoured by this many pixels
    float edgeFalloff    = 0.5f;  // strength at cone edge relative to centre (0..1)
};

// Projects a world point to screen pixels. Returns false if behind the camera
// or outside the clip volume. Screen origin is top-left, +y down.
bool WorldToScreen(const Mat4& vp, const Vec3& p, int width, int height, Vec2& out) {
    const float cx = vp.m[0][0] * p.x + vp.m[0][1] * p.y + vp.m[0][2] * p.z + vp.m[0][3];
    const float cy = vp.m[1][0] * p.x + vp.m[1][1] * p.y + vp.m[1][2] * p.z + vp.m[1][3];
    const float cw = vp.m[3][0] * p.x + vp.m[3][1] * p.y + vp.m[3][2] * p.z + vp.m[3][3];
    if (cw < 1e-4f) return false;

    const float nx = cx / cw;
    const float ny = cy / cw;
    if (nx < -1.f || nx > 1.f || ny < -1.f || ny > 1.f) return false;

    out.x = (nx * 0.5f + 0.5f) * static_cast<float>(width);
    out.y = (1.f - (ny * 0.5f + 0.5f)) * static_cast<float>(height);
    return true;
}

class AimAssist {
public:
    explicit AimAssist(const Config& cfg = Config{}) : cfg_(cfg) {}

    void SetConfig(const Config& cfg) { cfg_ = cfg; }
    void Reset() { hasTarget_ = false; targetId_ = 0; }
    bool HasTarget() const { return hasTarget_; }
    uint32_t TargetId() const { return targetId_; }

    // Returns the crosshair delta (pixels) to apply this frame.
    Vec2 Update(const Mat4& viewProj, const std::vector<Entity>& entities,
                int width, int height, float dtSec) {
        const Vec2 centre{ width * 0.5f, height * 0.5f };
        Vec2 best{};
        float bestScore = 1e30f;
        float bestDist = 0.f;
        uint32_t bestId = 0;
        bool found = false;

        for (const Entity& e : entities) {
            if (!e.alive || !e.visible) continue;
            Vec2 s;
            if (!WorldToScreen(viewProj, e.head, width, height, s)) continue;

            const float dx = s.x - centre.x;
            const float dy = s.y - centre.y;
            const float dist = std::sqrt(dx * dx + dy * dy);
            if (dist > cfg_.coneRadiusPx) continue;

            float score = dist;
            if (hasTarget_ && e.id == targetId_) score -= cfg_.stickyBonusPx;
            if (score < bestScore) {
                bestScore = score; best = s; bestDist = dist; bestId = e.id; found = true;
            }
        }

        if (!found || dtSec <= 0.f) {
            if (!found) Reset();
            return Vec2{};
        }
        hasTarget_ = true;
        targetId_ = bestId;

        // Frame-rate independent exponential smoothing.
        const float tau = std::max(cfg_.smoothTimeSec, 1e-4f);
        const float alpha = 1.f - std::exp(-dtSec / tau);

        // Strength tapers linearly toward the cone edge.
        const float t = bestDist / cfg_.coneRadiusPx;
        const float strength = 1.f + (cfg_.edgeFalloff - 1.f) * t;

        Vec2 d{ (best.x - centre.x) * alpha * strength,
                (best.y - centre.y) * alpha * strength };

        const float maxStep = cfg_.maxSpeedPxSec * dtSec;
        const float len = std::sqrt(d.x * d.x + d.y * d.y);
        if (len > maxStep && len > 0.f) {
            const float k = maxStep / len;
            d.x *= k; d.y *= k;
        }
        return d;
    }

private:
    Config   cfg_;
    bool     hasTarget_ = false;
    uint32_t targetId_ = 0;
};

} // namespace aim

#ifdef AIM_SMOKE
#include <cstdio>

static aim::Mat4 Perspective(float fovY, float aspect, float zn, float zf) {
    aim::Mat4 r;
    const float f = 1.f / std::tan(fovY * 0.5f);
    r.m[0][0] = f / aspect;
    r.m[1][1] = f;
    r.m[2][2] = zf / (zf - zn);
    r.m[2][3] = -zn * zf / (zf - zn);
    r.m[3][2] = 1.f; // camera at origin looking down +z
    return r;
}

int main() {
    const int W = 1920, H = 1080;
    const aim::Mat4 vp = Perspective(1.0472f, float(W) / H, 0.1f, 1000.f);

    std::vector<aim::Entity> ents = {
        {1, {0.6f, 0.2f, 10.f}},
        {2, {-4.f, 1.f, 10.f}},   // outside cone
        {3, {0.f, 0.f, -5.f}},    // behind camera
    };

    aim::AimAssist assist;
    for (int i = 0; i < 5; ++i) {
        aim::Vec2 d = assist.Update(vp, ents, W, H, 1.f / 60.f);
        std::printf("frame %d target=%u delta=(%.2f, %.2f)\n",
                    i, assist.TargetId(), d.x, d.y);
    }
    return 0;
}
#endif
